tags.description:
// Get built-in icon
svg('check')
svg('settings')

// Extend with custom icons
svg.extend({
  myIcon: '<path d="M12 2L2 22h20L12 2z"/>',
  logo: '<circle cx="12" cy="12" r="10"/>'
})
svg('myIcon') // Now available

// List all icons
svg.list() // ['check', 'x', 'plus', ..., 'myIcon', 'logo']

